export const unitById = id => ENGLISH_UNITS.find(u => u.id === id);

export const cleanWord = w => w.replace(/[^\p{L}\p{N}'’-]/gu, '').replace(/’/g, "'");
export const normalizeText = s => String(s).trim().toLowerCase().replace(/[’‘]/g, "'").replace(/\s+/g, ' ');
